from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse, Response
from starlette.middleware.base import BaseHTTPMiddleware


JS = r'''(()=>{
'use strict';
const API_BASE='/iphone/api/owner/forge';
const ROOT_ID='vishnuForgeConsole';
const LAUNCH_ID='vishnuForgeLauncher';
let state={summary:null,gaps:[],capabilities:[],lastProposal:null,lastWork:null,lastBuild:null,pendingActions:{}};
let loading=false;
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const toast=message=>typeof window.showToast==='function'?window.showToast(String(message)):console.info(message);
async function api(path,options={}){
  if(typeof window.api==='function') return window.api('/owner/forge'+path,options);
  const response=await fetch(API_BASE+path,{credentials:'same-origin',cache:'no-store',...options});
  let data={};try{data=await response.json()}catch{}
  if(!response.ok){const detail=data.detail;throw new Error(typeof detail==='string'?detail:(detail?.message||`Request failed (${response.status})`))}
  return data;
}
function installStyle(){if(document.getElementById('forge-console-style'))return;const s=document.createElement('style');s.id='forge-console-style';s.textContent=`
#${LAUNCH_ID}{position:fixed;right:18px;bottom:88px;z-index:2147483000;border:1px solid rgba(134,160,255,.35);background:rgba(12,18,31,.92);color:#eef3ff;border-radius:999px;padding:10px 14px;font-weight:750;box-shadow:0 14px 40px rgba(0,0,0,.36);backdrop-filter:blur(18px);cursor:pointer}
#${ROOT_ID}{position:fixed;inset:0;z-index:2147483001;background:rgba(2,5,10,.7);backdrop-filter:blur(16px);display:none;align-items:stretch;justify-content:flex-end;color:#f6f8fc;font:14px/1.45 -apple-system,BlinkMacSystemFont,"SF Pro Text",Inter,sans-serif}#${ROOT_ID}.open{display:flex}.forge-shell{width:min(760px,100%);background:#090d15;border-left:1px solid #283246;overflow:auto;padding:max(18px,env(safe-area-inset-top)) 18px max(26px,env(safe-area-inset-bottom));box-shadow:-24px 0 70px rgba(0,0,0,.4)}
.forge-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}.forge-head h2{font-size:28px;margin:2px 0 4px}.forge-muted{color:#98a6bc}.forge-close,.forge-btn{border:1px solid #344057;background:#151d2b;color:#eef3ff;border-radius:11px;padding:9px 11px;cursor:pointer}.forge-btn.primary{background:#e0e9ff;color:#101725;border-color:#e0e9ff;font-weight:800}.forge-btn.danger{border-color:#70424a;color:#ffc1ca;background:#261318}.forge-tabs{display:flex;gap:7px;overflow:auto;padding:16px 0 10px;position:sticky;top:0;background:#090d15;z-index:2}.forge-tab{white-space:nowrap;border:1px solid #2d374b;border-radius:999px;padding:7px 10px;color:#aebbd0;background:#0f1520;cursor:pointer}.forge-tab.active{color:#fff;border-color:#6683cc;background:#17223a}.forge-view{display:none}.forge-view.active{display:block}.forge-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.forge-stat,.forge-card{border:1px solid #273146;background:#0d131e;border-radius:16px;padding:14px}.forge-stat strong{display:block;font-size:23px}.forge-card{margin-top:10px}.forge-row{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.forge-badges{display:flex;flex-wrap:wrap;gap:6px}.forge-badge{font-size:11px;padding:5px 8px;border:1px solid #344057;border-radius:999px;color:#b8c5d8}.forge-badge.ok{color:#a8e7c4;border-color:#285b45}.forge-badge.warn{color:#ffd28f;border-color:#624d29}.forge-form{display:grid;gap:10px}.forge-form label{display:grid;gap:5px;color:#acb9cc}.forge-form input,.forge-form textarea,.forge-form select{width:100%;border:1px solid #303b51;background:#080c13;color:#f6f8fc;border-radius:11px;padding:10px;font:inherit}.forge-form textarea{min-height:90px;resize:vertical}.forge-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.forge-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;color:#aab9ce;overflow-wrap:anywhere}.forge-empty{padding:20px;text-align:center;color:#8290a6}.forge-safety{display:grid;gap:8px}.forge-safety div{border:1px solid #2d374b;border-radius:12px;padding:11px}.forge-notice{min-height:22px;color:#a7b7ce;padding:8px 0}.forge-timeline{display:grid;gap:8px}.forge-step{display:grid;grid-template-columns:12px 1fr;gap:10px;align-items:start}.forge-dot{width:9px;height:9px;margin-top:5px;border-radius:50%;background:#43506a}.forge-dot.done{background:#66d39b;box-shadow:0 0 12px rgba(102,211,155,.45)}@media(max-width:700px){.forge-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.forge-shell{border-left:0}.forge-head h2{font-size:23px}}@media(max-width:420px){.forge-grid{grid-template-columns:1fr 1fr}#${LAUNCH_ID}{right:12px;bottom:76px}.forge-shell{padding-left:12px;padding-right:12px}}
`;document.head.appendChild(s)}
function statusBadge(value){const v=String(value||'unknown');const cls=['active','qualified','healthy','packaged','completed'].some(x=>v.includes(x))?'ok':(['failed','blocked','rollback'].some(x=>v.includes(x))?'warn':'');return `<span class="forge-badge ${cls}">${esc(v)}</span>`}
function summaryView(){const s=state.summary||{};return `<div class="forge-grid"><div class="forge-stat"><span class="forge-muted">Capability gaps</span><strong>${esc(s.gaps??0)}</strong></div><div class="forge-stat"><span class="forge-muted">Open gaps</span><strong>${esc(s.open_gaps??0)}</strong></div><div class="forge-stat"><span class="forge-muted">Generated</span><strong>${esc(s.generated_capabilities??0)}</strong></div><div class="forge-stat"><span class="forge-muted">Active</span><strong>${esc(s.active_generated_capabilities??0)}</strong></div></div><div class="forge-card"><div class="forge-row"><div><strong>Governed self-created capabilities</strong><div class="forge-muted">Forge may propose and build in isolation, but Canonical Work, Engineering qualification, owner approvals and ToolRegistry remain authoritative.</div></div>${statusBadge(s.engineering_available?'engineering ready':'engineering unavailable')}</div></div>`}
function gapsView(){const cards=(state.gaps||[]).map(g=>`<article class="forge-card"><div class="forge-row"><div><strong>${esc(g.name||g.capability_name||g.id)}</strong><div class="forge-code">${esc(g.id)}</div></div>${statusBadge(g.status)}</div><div class="forge-muted" style="margin-top:8px">${esc(g.requested_outcome||g.reason||g.summary||'Capability gap')}</div></article>`).join('')||'<div class="forge-empty">No capability gaps recorded.</div>';return `<div class="forge-card"><strong>Propose a capability</strong><form id="forgeProposalForm" class="forge-form" style="margin-top:10px"><label>Name<input name="capability_name" required maxlength="240" placeholder="Supplier price monitor"></label><label>Requested outcome<textarea name="requested_outcome" required maxlength="1000" placeholder="Monitor supplier prices and return normalized changes"></textarea></label><label>Required operations<input name="required_operations" placeholder="fetch data, normalize values"></label><label>Preferred route<select name="preferred_route"><option value="">Let Vishnu choose</option><option value="generated">Generated capability</option><option value="openapi_discovery">OpenAPI</option><option value="mcp_discovery">MCP</option><option value="composition">Existing capability composition</option></select></label><div class="forge-actions"><button class="forge-btn primary" type="submit">Create proposal</button></div></form><div id="forgeProposalResult" class="forge-notice"></div></div>${cards}`}
function buildView(){const p=state.lastProposal;const w=state.lastWork;const b=state.lastBuild;return `<div class="forge-card"><strong>1 · Create governed Canonical Work</strong><form id="forgeWorkForm" class="forge-form" style="margin-top:10px"><label>Spec ID<input name="spec_id" required value="${esc(p?.spec?.id||'')}"></label><label>Plan ID<input name="plan_id" required value="${esc(p?.plan?.id||'')}"></label><label>Repository<input name="repository" required value="vaishnavsawant1994-stack/vishnu"></label><label>Allowed paths<input name="allowed_paths" required placeholder="generated-capabilities/my-capability"></label><div class="forge-actions"><button class="forge-btn primary" type="submit">Create draft WorkOrder</button></div></form><div id="forgeWorkResult" class="forge-notice">${w?`WorkOrder: <span class="forge-code">${esc(w.work_order?.id)}</span> · still ${esc(w.work_order?.status||'draft')}`:'Draft work never starts execution automatically.'}</div></div><div class="forge-card"><strong>2 · Build after Canonical Work queues it</strong><form id="forgeBuildForm" class="forge-form" style="margin-top:10px"><label>WorkOrder ID<input name="work_order_id" required value="${esc(w?.work_order?.id||'')}"></label><label>Source root<input name="source_root" required placeholder="generated-capabilities/my-capability"></label><label>Version<input name="version" required value="1.0.0"></label><div class="forge-actions"><button class="forge-btn primary" type="submit">Run governed build</button><button class="forge-btn" type="button" data-refresh-build>Refresh status</button></div></form><div class="forge-timeline" style="margin-top:12px">${buildTimeline(b)}</div><div id="forgeBuildResult" class="forge-notice"></div></div>`}
function buildTimeline(build){const payload=build?.payload||{};const status=String(build?.status||'not started');const stages=[['Capability gap',true],['Frozen spec / plan',true],['Canonical Work',!!(state.lastWork?.work_order?.id)],['Isolated Engineering Runtime',!!build],['Verification / repair / review',!!payload.qualification||status==='packaged'],['Immutable package',status==='packaged'],['Owner activation',false]];return stages.map(([label,done])=>`<div class="forge-step"><span class="forge-dot ${done?'done':''}"></span><div><strong>${esc(label)}</strong>${label==='Immutable package'&&build?`<div class="forge-code">${esc(build.id||'')} · ${esc(payload.version||'')}</div>`:''}</div></div>`).join('')}
function pendingActionView(capabilityId){const pending=state.pendingActions[capabilityId];if(!pending)return '';if(pending.action==='disable')return `<div class="forge-notice">Disable approval <span class="forge-code">${esc(pending.ticket_id)}</span> is pending. Approve it in Approvals Center, then commit here.</div><div class="forge-actions"><button class="forge-btn danger" data-commit-disable="${esc(capabilityId)}">Commit approved disable</button></div>`;if(pending.action==='rollback')return `<div class="forge-notice">Rollback to v${esc(pending.target_version)} needs approval <span class="forge-code">${esc(pending.ticket_id)}</span>.</div><div class="forge-actions"><button class="forge-btn danger" data-commit-rollback="${esc(capabilityId)}">Commit approved rollback</button></div>`;return ''}
function capabilitiesView(){const cards=(state.capabilities||[]).map(c=>{const m=c.metrics||{};return `<article class="forge-card"><div class="forge-row"><div><strong>${esc(c.name||c.id)}</strong><div class="forge-code">${esc(c.id)} · v${esc(c.version||'?')}</div></div>${statusBadge(c.state)}</div><div class="forge-badges" style="margin-top:9px"><span class="forge-badge">${esc(c.runtime||'runtime')}</span><span class="forge-badge">risk ${esc(c.risk||'?')}</span><span class="forge-badge">${esc(m.samples??0)} calls</span><span class="forge-badge">${esc(m.success_rate??m.successes??0)} success</span></div><div class="forge-actions"><button class="forge-btn" data-disable="${esc(c.id)}">Request disable</button><button class="forge-btn" data-rollback="${esc(c.id)}">Request rollback</button></div>${pendingActionView(c.id)}</article>`}).join('')||'<div class="forge-empty">No generated capabilities are registered yet.</div>';return `<div class="forge-card"><strong>Activate a packaged build</strong><div class="forge-form" style="margin-top:10px"><label>Build ID<input id="forgeActivationBuild" placeholder="build:attempt-id"></label><label>Approved ticket ID<input id="forgeActivationTicket" placeholder="Filled after approval"></label><div class="forge-actions"><button class="forge-btn primary" data-request-activation>Request activation approval</button><button class="forge-btn" data-commit-activation>Commit approved activation</button></div><div id="forgeActivationResult" class="forge-notice">Approval happens in Vishnu's existing Approvals Center. Forge cannot approve its own ticket.</div></div></div>${cards}`}
function safetyView(){const a=state.summary?.authorities||{};const pairs=[['Queue draft work',a.queue_draft_work],['Self-approve activation',a.self_approve_activation],['Remote push',a.remote_push],['Merge',a.merge],['Deploy',a.deploy],['Production activation',a.production_activation]];return `<div class="forge-safety">${pairs.map(([k,v])=>`<div class="forge-row"><strong>${esc(k)}</strong>${statusBadge(v?'enabled':'blocked')}</div>`).join('')}<div><strong>Generated runtime boundary</strong><p class="forge-muted">Pure capabilities run in an isolated, resource-limited Python process. Governed toolchain capabilities may only compose explicitly allowlisted, already-registered READ_ONLY Vishnu tools. Connector IDs, network hosts and filesystem read roots must stay inside the frozen Forge specification. Raw process environment, credentials, arbitrary filesystem access and side-effect authority are never delegated.</p></div></div>`}
function shell(){return `<div class="forge-shell" role="dialog" aria-modal="true" aria-label="Capability Forge"><div class="forge-head"><div><span class="forge-badge">Owner controls</span><h2>Capability Forge</h2><div class="forge-muted">Design, qualify, approve, monitor and roll back capabilities Vishnu creates for himself.</div></div><button class="forge-close" aria-label="Close Capability Forge">Close</button></div><nav class="forge-tabs" aria-label="Forge views">${['overview','gaps','build','generated','safety'].map((t,i)=>`<button class="forge-tab ${i===0?'active':''}" data-forge-tab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</nav><section class="forge-view active" data-forge-view="overview">${summaryView()}</section><section class="forge-view" data-forge-view="gaps">${gapsView()}</section><section class="forge-view" data-forge-view="build">${buildView()}</section><section class="forge-view" data-forge-view="generated">${capabilitiesView()}</section><section class="forge-view" data-forge-view="safety">${safetyView()}</section></div>`}
async function refresh(){if(loading)return;loading=true;try{const [summary,gaps,caps]=await Promise.all([api('/summary'),api('/gaps'),api('/capabilities')]);state.summary=summary;state.gaps=gaps.items||[];state.capabilities=caps.items||[];render()}catch(error){console.warn('Capability Forge UI unavailable',error)}finally{loading=false}}
function render(){const root=document.getElementById(ROOT_ID);if(!root)return;const open=root.classList.contains('open');root.innerHTML=shell();if(open)root.classList.add('open');bind(root)}
function showTab(root,name){root.querySelectorAll('[data-forge-tab]').forEach(b=>b.classList.toggle('active',b.dataset.forgeTab===name));root.querySelectorAll('[data-forge-view]').forEach(v=>v.classList.toggle('active',v.dataset.forgeView===name))}
function splitCsv(value){return String(value||'').split(',').map(x=>x.trim()).filter(Boolean)}
function bind(root){root.querySelector('.forge-close')?.addEventListener('click',()=>root.classList.remove('open'));root.addEventListener('click',e=>{if(e.target===root)root.classList.remove('open')});root.querySelectorAll('[data-forge-tab]').forEach(b=>b.addEventListener('click',()=>showTab(root,b.dataset.forgeTab)));
root.querySelector('#forgeProposalForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const result=await api('/proposals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source:'conversation',capability_name:f.get('capability_name'),requested_outcome:f.get('requested_outcome'),required_operations:splitCsv(f.get('required_operations')),preferred_route:f.get('preferred_route')||null,requirements:{}})});state.lastProposal=result;toast('Capability proposal created.');await refresh();const current=document.getElementById(ROOT_ID);current.classList.add('open');showTab(current,'build')}catch(error){document.getElementById('forgeProposalResult').textContent=error.message}});
root.querySelector('#forgeWorkForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{state.lastWork=await api('/work',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({spec_id:f.get('spec_id'),plan_id:f.get('plan_id'),repository:f.get('repository'),allowed_paths:splitCsv(f.get('allowed_paths')),priority:50,max_runtime_seconds:1800,max_attempts:3,prohibited_paths:[]})});toast('Draft Canonical Work created. Existing Work governance must queue it before execution.');render();const current=document.getElementById(ROOT_ID);current.classList.add('open');showTab(current,'build')}catch(error){document.getElementById('forgeWorkResult').textContent=error.message}});
root.querySelector('#forgeBuildForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/work/${encodeURIComponent(f.get('work_order_id'))}/build`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:f.get('version'),source_root:f.get('source_root')})});toast('Governed Forge build scheduled.');setTimeout(()=>refreshBuild(String(f.get('work_order_id'))),900)}catch(error){document.getElementById('forgeBuildResult').textContent=error.message}});
root.querySelector('[data-refresh-build]')?.addEventListener('click',()=>{const form=root.querySelector('#forgeBuildForm');const id=new FormData(form).get('work_order_id');if(id)refreshBuild(String(id))});
root.querySelector('[data-request-activation]')?.addEventListener('click',async()=>{const id=document.getElementById('forgeActivationBuild').value.trim();if(!id)return toast('Enter a packaged build ID.');try{const r=await api('/activation/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({build_id:id,ticket_id:null})});document.getElementById('forgeActivationTicket').value=r.ticket_id||'';document.getElementById('forgeActivationResult').textContent=`Approval ${r.ticket_id} created. Review it in Approvals Center, then return here to commit.`}catch(error){document.getElementById('forgeActivationResult').textContent=error.message}});
root.querySelector('[data-commit-activation]')?.addEventListener('click',async()=>{const build=document.getElementById('forgeActivationBuild').value.trim(),ticket=document.getElementById('forgeActivationTicket').value.trim();if(!build||!ticket)return toast('Build ID and approved ticket ID are required.');try{await api('/activation/commit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({build_id:build,ticket_id:ticket})});toast('Generated capability activated.');await refresh()}catch(error){document.getElementById('forgeActivationResult').textContent=error.message}});
root.querySelectorAll('[data-disable]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.disable;try{const r=await api(`/capabilities/${encodeURIComponent(id)}/disable/request`,{method:'POST'});state.pendingActions[id]={action:'disable',ticket_id:r.ticket_id};toast(`Disable approval ${r.ticket_id} created. Approve it in Approvals Center before commit.`);render();const current=document.getElementById(ROOT_ID);current.classList.add('open');showTab(current,'generated')}catch(error){toast(error.message)}}));
root.querySelectorAll('[data-commit-disable]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.commitDisable,pending=state.pendingActions[id];if(!pending?.ticket_id)return toast('Request a disable approval first.');try{await api(`/capabilities/${encodeURIComponent(id)}/disable/commit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ticket_id:pending.ticket_id})});delete state.pendingActions[id];toast('Generated capability disabled.');await refresh()}catch(error){toast(error.message)}}));
root.querySelectorAll('[data-rollback]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.rollback;try{const r=await api(`/capabilities/${encodeURIComponent(id)}/rollback/request`,{method:'POST'});state.pendingActions[id]={action:'rollback',ticket_id:r.ticket_id,target_activation_id:r.target_activation_id,target_version:r.target_version};toast(`Rollback to ${r.target_version} needs approval ${r.ticket_id}. Approve it in Approvals Center.`);render();const current=document.getElementById(ROOT_ID);current.classList.add('open');showTab(current,'generated')}catch(error){toast(error.message)}}));
root.querySelectorAll('[data-commit-rollback]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.commitRollback,pending=state.pendingActions[id];if(!pending?.ticket_id||!pending?.target_activation_id)return toast('Request a rollback approval first.');try{await api(`/capabilities/${encodeURIComponent(id)}/rollback/commit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ticket_id:pending.ticket_id,target_activation_id:pending.target_activation_id})});delete state.pendingActions[id];toast(`Generated capability rolled back to ${pending.target_version}.`);await refresh()}catch(error){toast(error.message)}}));}
async function refreshBuild(id){try{const r=await api(`/work/${encodeURIComponent(id)}/build`);state.lastBuild=r.build;render();const root=document.getElementById(ROOT_ID);root.classList.add('open');showTab(root,'build')}catch(error){toast(error.message)}}
function mount(){installStyle();if(!document.getElementById(ROOT_ID)){const root=document.createElement('div');root.id=ROOT_ID;root.innerHTML=shell();document.body.appendChild(root);bind(root)}if(!document.getElementById(LAUNCH_ID)){const b=document.createElement('button');b.id=LAUNCH_ID;b.type='button';b.textContent='Forge';b.addEventListener('click',async()=>{document.getElementById(ROOT_ID).classList.add('open');await refresh()});document.body.appendChild(b)}refresh()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount);else mount();
})();'''


_PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#090d15"><title>Vishnu · Capability Forge</title><style>html,body{margin:0;min-height:100%;background:#090d15;color:#f6f8fc;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text",Inter,sans-serif}body:before{content:"Capability Forge";display:block;padding:24px;font-weight:800;font-size:18px;color:#aebbd0}</style></head><body><script>window.showToast=message=>console.info(message)</script><script src="/iphone/capability-forge-ui.js"></script></body></html>'''


class CapabilityForgeUiMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request, call_next):
        response = await call_next(request)
        if request.url.path not in {"/iphone", "/iphone/", "/capabilities", "/capabilities/"} or response.status_code != 200:
            return response
        if "text/html" not in response.headers.get("content-type", ""):
            return response
        body = b""
        async for chunk in response.body_iterator:
            body += chunk
        text = body.decode("utf-8")
        marker = "</body>"
        script = '<script src="/iphone/capability-forge-ui.js"></script>'
        if marker in text and script not in text:
            text = text.replace(marker, script + marker, 1)
        headers = {key: value for key, value in response.headers.items() if key.lower() not in {"content-length", "content-encoding"}}
        return Response(text, status_code=response.status_code, headers=headers, media_type="text/html")


def capability_forge_ui_router() -> APIRouter:
    router = APIRouter()

    @router.get("/iphone/capability-forge-ui.js", include_in_schema=False)
    def forge_ui_js():
        return Response(JS, media_type="application/javascript", headers={"Cache-Control": "no-cache"})

    @router.get("/capabilities/forge", response_class=HTMLResponse, include_in_schema=False)
    def forge_console_page():
        return HTMLResponse(_PAGE, headers={"Cache-Control": "no-store"})

    return router
